package org.circus.core;
import java.awt.image.BufferedImage;import java.io.*;import java.nio.file.*;import java.util.*;import javax.imageio.ImageIO;
/** Admitted original DC2 Windows slots reconstructed into real portable player frames. */
public final class Dc2NativeImportAudit {
 private static int checks;private static void check(boolean yes,String why){checks++;if(!yes)throw new AssertionError(why);}
 private static int[] pixels(BufferedImage image){return image.getRGB(0,0,image.getWidth(),image.getHeight(),null,0,image.getWidth());}
 public static void main(String[]args)throws Exception{
  if(args.length!=2)throw new IOException("Require readonly_DC2_GAME owned_OUTPUT");Path game=Paths.get(args[0]).toRealPath(),out=DesktopRouteAudit.outputOutsideGame(game,args[1]);System.setProperty("dc.saveRoot",out.resolve("owned-saves").toString());GameResources files=new GameResources(new LocalGameStorage(game),"dc2.exe");CircusResources data=new CircusResources(files,Profiles.get("dc2-3363"));TextCodec codec=GameText.detect(files,data.profile);List<Object> records=new ArrayList<>();
  for(int n=0;n<5;n++){
   Path original=game.resolve("AdvData/SaveData/dc20"+n+".dat");byte[] raw=Files.readAllBytes(original);String digest=Binary.sha256(raw);Dc2NativeSlot slot=Dc2NativeSlot.parse(raw);MesScript caller=data.scripts().script(slot.scriptName());Dc2NativeSlot.Plan plan=slot.normalTextPlan(caller);DesktopLegacy engine=new DesktopLegacy(data,codec,true);engine.session.importDc2NativeSlot(slot);PcHost host=(PcHost)engine.host();
   check(engine.vm().scriptName().equals(plan.script)&&host.textWaiting&&!host.body.isEmpty(),"native import reaches actual checkpoint's text wait");check(host.ui.quadTemplates.get(1).size()>0&&host.ui.quadTemplates.get(2).size()>0&&host.ui.buttonTemplates.get(1).size()>0,"START supplies original global message/name/button templates");
   for(int i=0;i<1000;i++)check(engine.vm().variables.read(i/100,i%100)==(slot.ordinaryBytes()[i]&255),"ordinary byte preserved "+i);
   for(int k=0;k<4;k++)check(host.dc2ActorChange.staged[k]==slot.dword(new Dc2NativeSlot.Dword[]{Dc2NativeSlot.Dword.ACTOR1_STAGE_X,Dc2NativeSlot.Dword.ACTOR1_STAGE_Y,Dc2NativeSlot.Dword.ACTOR2_STAGE_X,Dc2NativeSlot.Dword.ACTOR2_STAGE_Y}[k]),"native staged actor word restored independently of active coordinates");
   check(host.scene.slots[1].equals(slot.resource(Dc2NativeSlot.StringField.BACKGROUND))&&host.scene.character(0,0)==slot.dword(Dc2NativeSlot.Dword.ACTOR1_X),"native scene paths/coordinates restored");check(host.logicalMusic()==slot.dword(Dc2NativeSlot.Dword.LOGICAL_MUSIC)&&!host.audio[0].isEmpty(),"native music request recreated");check(host.scene.nativeParticles.kind()==slot.dword(Dc2NativeSlot.Dword.EFFECT_KIND)&&(slot.dword(Dc2NativeSlot.Dword.EFFECT_KIND)==0||host.scene.nativeParticles.strength()==slot.dword(Dc2NativeSlot.Dword.EFFECT_STRENGTH)),"native particle kind/strength recreated "+host.scene.nativeParticles.kind()+","+host.scene.nativeParticles.strength()+" vs "+slot.dword(Dc2NativeSlot.Dword.EFFECT_KIND)+","+slot.dword(Dc2NativeSlot.Dword.EFFECT_STRENGTH));
   BufferedImage image=engine.render();int[] before=pixels(image);ImageIO.write(image,"png",out.resolve("dc20"+n+".png").toFile());image.flush();long colored=0;for(int pixel:before)if((pixel&0xffffff)!=0)colored++;check(colored>1000,"imported player draws actual scene and original UI");
   byte[] saved=engine.snapshot();engine.restore(saved);image=engine.render();check(Arrays.equals(before,pixels(image)),"portable save/restore preserves imported frame exactly");image.flush();
   engine.vm().signalHost(engine.ticket(),MesVm.HostSignal.ADVANCE);for(int i=0;i<1000;i++){engine.tick(40);if(engine.textWaiting()||engine.menuWaiting())break;for(int ch=0;ch<6;ch++)engine.audioCompleted(ch,engine.audioGeneration(ch));}check(engine.vm().status()!=MesVm.Status.FAULT&&engine.vm().offset()!=plan.resumeFilePc,"imported script continues to a later actual wait");
   MesVm prior=engine.vm();byte[] invalid=raw.clone();invalid[0]=0;boolean failed=false;try{engine.session.importDc2NativeSlot(Dc2NativeSlot.parse(invalid));}catch(IOException expected){failed=true;}check(failed&&engine.vm()==prior,"invalid original slot rejected before publishing current player");
   byte[] missing=raw.clone();Arrays.fill(missing,Dc2NativeSlot.StringField.BACKGROUND.offset,Dc2NativeSlot.StringField.BACKGROUND.offset+128,(byte)0);byte[] name="missing_import_asset".getBytes("US-ASCII");System.arraycopy(name,0,missing,Dc2NativeSlot.StringField.BACKGROUND.offset,name.length);failed=false;try{engine.session.importDc2NativeSlot(Dc2NativeSlot.parse(missing));}catch(IOException expected){failed=true;}check(failed&&engine.vm()==prior,"missing resource fails detached reconstruction without publishing");
   byte[] nvl=raw.clone();nvl[Dc2NativeSlot.Dword.PARAGRAPH_MODE.offset]=1;failed=false;try{engine.session.importDc2NativeSlot(Dc2NativeSlot.parse(nvl));}catch(IOException expected){failed=true;}check(failed&&engine.vm()==prior,"unsupported prior NVL paragraph remains precise rejection");check(Binary.sha256(Files.readAllBytes(original)).equals(digest),"original slot remains unchanged");records.add(Json.obj("file",original.getFileName().toString(),"sha256",digest,"script",plan.script,"raw_code_pc",plan.savedRawCodePc,"checkpoint_file_pc",plan.checkpointFilePc,"replayed_wait_file_pc",host.pc,"body_characters",host.body.length(),"native_log_words",slot.activeLogWords().length,"portable_backlog_prior_windows_rows_imported",false));
  }
  Files.write(out.resolve("result.json"),(Json.text(Json.obj("pass",true,"checks",checks,"slots",records,"original_exe_executed",false,"original_game_directory_written",false,"scope","Current original ADV wait7 checkpoint reconstruction with original START templates/resources, scene/audio/effects, portable snapshot and future story; previous Windows backlog/NVL/physical media cursor is outside import scope"))+"\n").getBytes("UTF-8"));System.out.println("Dc2NativeImportAudit "+checks+" PASS;5 original Windows slots");
 }
}
